// AGENT CONFIGURATION - change settings here
return [{
  json: {
    recipient: 'YOUR_EMAIL@example.com',   // where the daily email is sent
    model: 'gemini-3.5-flash',             // Gemini model name (check availability in Google AI Studio)
    requestedCount: 7,                     // dishes requested from the model (buffer for the onion filter)
    minimumCount: 5,                       // below this number the email shows a warning
    servings: 4,                           // servings used for ingredient amounts
    // case-insensitive fragments that reject a dish (Polish + English onion family)
    forbiddenPatterns: ['cebul', 'szczypior', 'szalot', 'dymk', 'onion', 'shallot', 'chive']
  }
}];

const cfg = $('Config').first().json;

// Today's date in Polish, Europe/Warsaw timezone
const now = new Date();
const dateLabel = now.toLocaleDateString('pl-PL', {
  timeZone: 'Europe/Warsaw', weekday: 'long', day: 'numeric', month: 'long', year: 'numeric'
});

// Random "inspirations of the day" - variety without storing history (values are Polish, sent to the model)
const inspirations = [
  'makarony', 'kasze', 'ryż', 'ziemniaki', 'zupy', 'dania z piekarnika', 'placki i naleśniki',
  'ryby', 'drób', 'wieprzowina', 'wołowina', 'mięso mielone', 'jajka', 'dania warzywne',
  'pierogi i kluski', 'kuchnia włoska', 'polska kuchnia domowa', 'łagodna kuchnia azjatycka',
  'łagodna kuchnia meksykańska', 'zapiekanki', 'gulasze i potrawki', 'kotlety'
];
const todaysInspirations = [...inspirations].sort(() => Math.random() - 0.5).slice(0, 4);

// System instruction (Polish - the model must answer in Polish)
const systemInstruction = `Jesteś doświadczonym kucharzem domowym, który gotuje obiady dla rodziny z dziećmi.

ZASADA NADRZĘDNA - ZERO CEBULI:
- Żaden przepis nie może zawierać cebuli w jakiejkolwiek postaci: surowej, smażonej, prażonej, duszonej, w proszku, jako bazy do smażenia.
- Wykluczone są też: szczypiorek, szalotka, dymka, cebula w proszku.
- Por jako warzywo JEST dozwolony. Czosnek jest dozwolony.
- Śladowe ilości w gotowych produktach (ketchup, mieszanki przypraw) nie mają znaczenia.
- Jeśli danie tradycyjnie zawiera cebulę, możesz je zaproponować w wersji bez cebuli. Wtedy w polu "onion_free_note" napisz krótko, że to danie tradycyjnie robi się z cebulą i czym ją zastąpiono lub dlaczego da się bez niej. W pozostałych daniach to pole zostaw puste.
- W polach "ingredients" i "steps" słowo cebula (ani szczypiorek, szalotka, dymka) nie może się pojawić w ogóle, nawet z dopiskiem "bez".

POZOSTAŁE ZASADY:
- Obiady dla całej rodziny, ale gotowane głównie pod dzieci: łagodne w smaku (bez ostrych przypraw), smaczne, apetyczne i zachęcające do jedzenia.
- Składniki z typowych domowych zapasów: lodówka, podstawowe warzywa, makaron, ryż, kasze, ziemniaki, jajka, mąka, podstawowe przyprawy. Bez egzotycznych i trudno dostępnych produktów.
- Zróżnicowany poziom trudności (pole "difficulty"): co najmniej 2 dania "easy" (szybkie, do 30 minut) i co najmniej 1 danie "demanding" (dłuższe przygotowanie).
- Dania mają się wyraźnie różnić od siebie (różne bazy, różne białka, różne techniki).
- Ilości składników podawaj na ${cfg.servings} porcje.
- Kroki przygotowania krótkie i konkretne.
- Wszystkie teksty pisz po polsku.`;

const userPrompt = `Dzisiaj jest ${dateLabel}. Zaproponuj dokładnie ${cfg.requestedCount} różnych obiadów.
Dzisiejsze inspiracje (wykorzystaj je w części propozycji, nie musisz we wszystkich): ${todaysInspirations.join(', ')}.`;

const requestBody = {
  systemInstruction: { parts: [{ text: systemInstruction }] },
  contents: [{ role: 'user', parts: [{ text: userPrompt }] }],
  generationConfig: {
    temperature: 1.0,
    maxOutputTokens: 8192,
    responseMimeType: 'application/json',
    responseSchema: {
      type: 'OBJECT',
      properties: {
        meals: {
          type: 'ARRAY',
          items: {
            type: 'OBJECT',
            properties: {
              name: { type: 'STRING' },
              description: { type: 'STRING', description: 'Jedno-dwa zdania: czym jest danie i dlaczego dzieci je polubią' },
              difficulty: { type: 'STRING', enum: ['easy', 'medium', 'demanding'] },
              time_minutes: { type: 'INTEGER' },
              ingredients: { type: 'ARRAY', items: { type: 'STRING' } },
              steps: { type: 'ARRAY', items: { type: 'STRING' } },
              onion_free_note: { type: 'STRING' }
            },
            required: ['name', 'description', 'difficulty', 'time_minutes', 'ingredients', 'steps', 'onion_free_note']
          }
        }
      },
      required: ['meals']
    }
  }
};

return [{ json: { requestBody, dateLabel, inspirations: todaysInspirations } }];

const cfg = $('Config').first().json;
const response = $input.first().json;

let meals = [];
let error = null;

// 1. Parse the model response (skip "thought" parts of thinking models)
try {
  const parts = response.candidates?.[0]?.content?.parts || [];
  const text = parts.filter(p => !p.thought).map(p => p.text || '').join('');
  meals = JSON.parse(text).meals || [];
} catch (e) {
  error = 'Nie udało się odczytać odpowiedzi modelu: ' + e.message;   // shown in the email (Polish)
}

// 2. Deterministic onion filter
const forbidden = new RegExp(cfg.forbiddenPatterns.join('|'), 'i');
// name/description may say "bez cebuli" ("without onion"); ingredients/steps may not mention onion at all
const stripWithoutOnion = s => String(s || '').replace(/bez\s+(dodatku\s+)?cebul\w*/gi, '');

const accepted = [];
const rejected = [];

for (const meal of meals) {
  const strictText = [...(meal.ingredients || []), ...(meal.steps || [])].join(' ');
  const lenientText = stripWithoutOnion(meal.name) + ' ' + stripWithoutOnion(meal.description);
  if (forbidden.test(strictText) || forbidden.test(lenientText)) {
    rejected.push(meal.name || '(no name)');
  } else {
    accepted.push(meal);
  }
}

return [{
  json: {
    meals: accepted,
    count: accepted.length,
    rejected,
    error,
    dateLabel: $('Build Prompt').first().json.dateLabel
  }
}];

const cfg = $('Config').first().json;
const data = $input.first().json;

const escapeHtml = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// Difficulty codes -> Polish labels and colours shown in the email
const difficulty = {
  easy:      { label: 'łatwe',               color: '#2e7d32' },
  medium:    { label: 'średnie',             color: '#ef6c00' },
  demanding: { label: 'bardziej wymagające', color: '#c62828' }
};

let warnings = '';
if (data.error) {
  warnings += `<p style="background:#ffebee;padding:10px;border-radius:6px;">⚠️ ${escapeHtml(data.error)}</p>`;
}
if (data.count < cfg.minimumCount) {
  warnings += `<p style="background:#fff3e0;padding:10px;border-radius:6px;">⚠️ Dziś kontrolę przeszło tylko ${data.count} propozycji (minimum to ${cfg.minimumCount}).</p>`;
}

const cards = data.meals.map((meal, i) => {
  const d = difficulty[meal.difficulty] || { label: meal.difficulty, color: '#333' };
  return `
  <div style="border:1px solid #ddd;border-radius:8px;padding:14px;margin:14px 0;">
    <h2 style="margin:0 0 6px 0;font-size:18px;">${i + 1}. ${escapeHtml(meal.name)}</h2>
    <p style="margin:0 0 8px 0;color:#555;">
      <span style="color:${d.color};font-weight:bold;">${escapeHtml(d.label)}</span>
      &nbsp;·&nbsp; ⏱️ ok. ${escapeHtml(meal.time_minutes)} min
    </p>
    <p style="margin:0 0 8px 0;">${escapeHtml(meal.description)}</p>
    ${meal.onion_free_note ? `<p style="background:#fff8e1;padding:8px;border-radius:6px;margin:0 0 8px 0;">🧅🚫 <b>Wersja bez cebuli:</b> ${escapeHtml(meal.onion_free_note)}</p>` : ''}
    <p style="margin:8px 0 4px 0;"><b>Składniki (${cfg.servings} porcje):</b></p>
    <ul style="margin:0;">${(meal.ingredients || []).map(s => `<li>${escapeHtml(s)}</li>`).join('')}</ul>
    <p style="margin:8px 0 4px 0;"><b>Przygotowanie:</b></p>
    <ol style="margin:0;">${(meal.steps || []).map(s => `<li>${escapeHtml(s)}</li>`).join('')}</ol>
  </div>`;
}).join('');

const html = `
<div style="font-family:Arial,sans-serif;max-width:680px;margin:auto;color:#222;">
  <h1 style="font-size:22px;">🍽️ Propozycje obiadów · ${escapeHtml(data.dateLabel)}</h1>
  ${warnings}
  ${cards}
  <p style="color:#999;font-size:12px;">Wygenerowane automatycznie przez agenta n8n · model: ${escapeHtml(cfg.model)}${data.rejected.length ? ' · odrzucone przez kontrolę cebuli: ' + data.rejected.length : ''}</p>
</div>`;

return [{ json: { subject: `🍽️ Propozycje obiadów · ${data.dateLabel}`, html } }];
